def getSym():
  global sym, val
  while ch in ' ':
    getChar()
  if 'A' <= ch <= 'Z' or 'a' <= ch <= 'z':
    start = pos - 1
    while ('A' <= ch <= 'Z') or ('a' <= ch <= 'z') or ('0' <= ch <= '9'):
      getChar()
    val = src[start : pos - 1]
    sym = KEYWORDS[val] if val in KEYWORDS else IDENT
  elif '0' <= ch <= '9':
    val = int(ch)
    getChar()
    while '0' <= ch <= '9':
      val = 10 * val + int(ch)
      getChar()
    sym = NUMBER
  elif ch == '×':
    getChar()
    sym = TIMES
  elif ch == '+':
    getChar()
    sym = PLUS
  elif ch == '-':
    getChar()
    sym = MINUS
  elif ch == '=':
    getChar()
    sym = EQ
  elif ch == '≠':
    getChar()
    sym = NEQ
  elif ch == '<':
    getChar()
    sym = LT
  elif ch == '>':
    getChar()
    sym = GT
  elif ch == '≤':
    getChar()
    sym = LE
  elif ch == '≥':
    getChar()
    sym = GE
  elif ch == '(':
    getChar()
    sym = LPAREN
  elif ch == ')':
    getChar()
    sym = RPAREN
  elif ch == ',':
    getChar()
    sym = COMMA
  elif ch == chr(0):
