#### Parser

In the abstract syntax tree, a constant is treated as a null-ary (parameterless) function, e.g. `let c = 1 in c + 2`, declares a null-ary function `c` and "calls" it.

```python
class Call:
  def __init__(self, name, args):
    self.name, self.args = name, args

  def __repr__(self):
    return (
      'Call('
      + self.name
      + ', ['
      + ', '.join([str(x) for x in self.args])
      + '])'
    )

class Unary:
  def __init__(self, op, operand):
    self.op, self.operand = op, operand

  def __repr__(self):
    return 'Unary(' + str(self.op) + ', ' + str(self.operand) + ')'

class Binary:
  def __init__(self, op, left, right):
    self.op, self.left, self.right = op, left, right

  def __repr__(self):
    return (
      'Binary('
      + str(self.op)
      + ', '
      + str(self.left)
      + ', '
      + str(self.right)
      + ')'
    )

class If:
  def __init__(self, cond, th, el):
    self.cond, self.th, self.el = cond, th, el

  def __repr__(self):
    return (
      'If(' + str(self.cond) + ', ' + str(self.th) + ', ' + str(self.el) + ')'
    )

class Let:
  def __init__(self, name, par, body, scope):
    self.name, self.par, self.body, self.scope = name, par, body, scope

  def __repr__(self):
    return (
      'Let('
      + self.name
      + ', '
      + str(self.par)
      + ', '
      + str(self.body)
      + ', '
      + str(self.scope)
      + ')'
    )
